// Mechanic folders (docs/ai/json-game-modules/MECHANICS-ARCHITECTURE.md): one per behaviour tag and status,
// generated by tools/mechanics-generate.mjs, with hand-authored portable services for a core set.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { validateGameSchema } from '../engine/kernel/gameConfig.js';
import { statuses } from '../src/content/statuses.js';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const MECHANICS = `${ROOT}engine/mechanics/`;
const readJson = path => JSON.parse(readFileSync(path, 'utf8'));
const schema = name => readJson(`${ROOT}engine/contracts/${name}.schema.json`);
const SCHEMAS = { manifest: schema('mechanic'), interface: schema('mechanic-interface'), service: schema('mechanic-service'), cases: schema('mechanic-cases') };
const FAMILIES = new Set('fx damage lifecycle trait maneuver camp targeting school cost scaling delivery counter range utility technique classification equipment theme source from item internal'.split(' '));
const PORTABLE_OPS = new Set('damage block loseHp heal applyStatus removeStatus draw discard exhaust addCard gainEnergy restoreStamina restoreMana poiseDamage gainPoise restorePoise stagger'.split(' '));

const folders = readdirSync(MECHANICS, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name).sort();
const manifests = Object.fromEntries(folders.map(slug => [slug, readJson(`${MECHANICS}${slug}/mechanic.json`)]));

function nodeIds() {
  const text = readFileSync(`${ROOT}content/source/nodes.csv`, 'utf8').split('\n').filter(l => !l.startsWith('#')).join('\n');
  const ids = []; let cell = '', row = [], quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) { if (c === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else quoted = false; } else cell += c; }
    else if (c === '"') quoted = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\n') { row.push(cell); ids.push(row[0]); row = []; cell = ''; }
    else cell += c;
  }
  return ids.slice(1).filter(id => { const m = id.match(/^([A-Za-z]+)[:.]/); return m && FAMILIES.has(m[1]); });
}
function* walk(value) {
  if (typeof value === 'string') yield value;
  else if (Array.isArray(value)) for (const item of value) yield* walk(item);
  else if (value && typeof value === 'object') for (const [k, v] of Object.entries(value)) { yield k; yield* walk(v); }
}
function* steps(list) {
  for (const step of list || []) { yield step; yield* steps(step.then); yield* steps(step.else); yield* steps(step.do); }
}

test('every mechanic folder has contract-valid manifest, interface, service and cases', () => {
  assert.ok(folders.length > 0);
  for (const slug of folders) {
    const manifest = manifests[slug];
    validateGameSchema(manifest, SCHEMAS.manifest, `${slug}/mechanic.json`);
    for (const key of ['model', 'interface', 'service', 'cases', 'guide']) assert.ok(existsSync(`${MECHANICS}${slug}/${manifest.files[key]}`), `${slug}: missing ${key} file`);
    const model = readJson(`${MECHANICS}${slug}/${manifest.files.model}`);
    assert.equal(model.type, 'object', `${slug}: model type`);
    assert.ok(['entity', 'card', 'combat', 'run', 'none'].includes(model['x-attach']), `${slug}: x-attach`);
    validateGameSchema(readJson(`${MECHANICS}${slug}/${manifest.files.interface}`), SCHEMAS.interface, `${slug}/interface.json`);
    validateGameSchema(readJson(`${MECHANICS}${slug}/${manifest.files.service}`), SCHEMAS.service, `${slug}/service.json`);
    validateGameSchema(readJson(`${MECHANICS}${slug}/${manifest.files.cases}`), SCHEMAS.cases, `${slug}/cases.json`);
    const lines = readFileSync(`${MECHANICS}${slug}/${manifest.files.guide}`, 'utf8').split('\n').filter(Boolean);
    assert.ok(lines.length >= 3 && lines.length <= 6, `${slug}: guide.md is ${lines.length} lines`);
  }
});

test('folder, id, tag, interface and service agree', () => {
  const slugs = new Set();
  for (const slug of folders) {
    const m = manifests[slug];
    assert.equal(m.id, slug, `${slug}: id`);
    assert.equal(m.id, m.tag.replace(/:/g, '_'), `${slug}: slug is tag with ':' replaced`);
    assert.ok(!slugs.has(m.tag), `${slug}: duplicate tag`); slugs.add(m.tag);
    assert.equal(readJson(`${MECHANICS}${slug}/interface.json`).mechanic, slug);
    assert.equal(readJson(`${MECHANICS}${slug}/service.json`).mechanic, slug);
    assert.equal(m.presentation?.icon, slug, `${slug}: presentation.icon is the slug`);
  }
});

test('every behaviour tag and every status has a mechanic', () => {
  const tags = new Set(Object.values(manifests).map(m => m.tag));
  for (const id of nodeIds()) assert.ok(tags.has(id), `no mechanic for tag ${id}`);
  for (const status of statuses) assert.ok(tags.has(`status.${status.id}`), `no mechanic for status ${status.id}`);
});

test('index.json matches the folders', () => {
  const index = readJson(`${MECHANICS}index.json`);
  assert.equal(index.format, 'ashen.mechanics-index@1');
  assert.deepEqual(index.mechanics.map(m => m.id), folders);
  for (const entry of index.mechanics) {
    const m = manifests[entry.id];
    assert.deepEqual({ tag: entry.tag, family: entry.family, portability: entry.portability }, { tag: m.tag, family: m.family, portability: m.portability }, entry.id);
    assert.ok(Array.isArray(entry.modules) && entry.modules.every(id => existsSync(`${ROOT}engine/modules/${id}/module.json`)), `${entry.id}: modules`);
    assert.deepEqual(entry.modules, [...entry.modules].sort(), `${entry.id}: modules sorted`);
  }
});

test('no glyphs in any mechanic JSON', () => {
  for (const slug of folders) for (const file of readdirSync(`${MECHANICS}${slug}`).filter(f => f.endsWith('.json'))) {
    for (const text of walk(readJson(`${MECHANICS}${slug}/${file}`))) assert.match(text, /^[\x20-\x7E]*$/, `${slug}/${file}: non-ASCII value`);
  }
  for (const text of walk(readJson(`${MECHANICS}index.json`))) assert.match(text, /^[\x20-\x7E]*$/, 'index.json: non-ASCII value');
});

test('legacy mechanics name an existing file; data mechanics name none', () => {
  for (const [slug, m] of Object.entries(manifests)) {
    if (m.portability === 'legacy') { assert.ok(m.legacy?.file, `${slug}: legacy needs a file`); assert.ok(existsSync(`${ROOT}${m.legacy.file}`), `${slug}: ${m.legacy.file} missing`); }
    if (m.portability === 'data') assert.equal(m.legacy, undefined, `${slug}: data mechanic names a legacy file`);
  }
});

test('portable mechanics are authored, use catalog ops and carry at least three cases', () => {
  const portable = Object.entries(manifests).filter(([, m]) => m.portability === 'portable');
  assert.ok(portable.length >= 8, 'core portable set');
  for (const [slug, m] of portable) {
    assert.equal(m.authored, true, `${slug}: portable mechanics are hand-authored`);
    const service = readJson(`${MECHANICS}${slug}/service.json`), cases = readJson(`${MECHANICS}${slug}/cases.json`);
    assert.ok(service.handlers.length > 0, `${slug}: service has handlers`);
    for (const handler of service.handlers) for (const step of steps(handler.do)) if (step.op) assert.ok(PORTABLE_OPS.has(step.op), `${slug}: op ${step.op} is not in the portable catalog`);
    assert.ok(cases.length >= 3, `${slug}: needs at least 3 cases`);
    const iface = readJson(`${MECHANICS}${slug}/interface.json`);
    for (const c of cases) {
      assert.ok(c.when.command || c.when.event, `${slug}: case "${c.name}" has no command or event`);
      if (c.when.command) assert.ok(c.when.command.startsWith(`${slug}.`) && c.when.command.slice(slug.length + 1) in (iface.commands || {}), `${slug}: case "${c.name}" names an unknown command`);
      for (const event of c.then.events || []) assert.ok(event.startsWith(`${slug}.`) && event.slice(slug.length + 1) in (iface.events || {}), `${slug}: case "${c.name}" expects an unknown event`);
    }
  }
});

test('the generator is idempotent (--check finds nothing to change)', () => {
  const run = spawnSync(process.execPath, [`${ROOT}tools/mechanics-generate.mjs`, '--check'], { encoding: 'utf8' });
  assert.equal(run.status, 0, run.stderr || run.stdout);
});
